依赖注入（Dependency Injection, DI）是 .NET Core 的核心特性之一，它实现了控制反转（IoC）原则，让对象的创建和依赖管理由容器负责。


## 依赖注入的基本概念

**依赖注入的三种方式**：
1. **构造函数注入**（推荐）：通过构造函数传入依赖
2. **属性注入**：通过公共属性设置依赖
3. **方法注入**：通过方法参数传入依赖

```csharp
// 构造函数注入（推荐）
public class OrderService
{
    private readonly IOrderRepository _repository;

    public OrderService(IOrderRepository repository)
    {
        _repository = repository;
    }
}
```

## .NET Core 内置 DI 容器

.NET Core 提供了内置的 DI 容器 `IServiceCollection` 和 `IServiceProvider`：

```csharp
// 注册服务
services.AddScoped<IOrderRepository, OrderRepository>();
services.AddScoped<IOrderService, OrderService>();

// 使用服务
var serviceProvider = services.BuildServiceProvider();
var orderService = serviceProvider.GetRequiredService<IOrderService>();
```


## 生命周期

.NET Core DI 容器支持三种生命周期：

**Transient（瞬态）**：每次请求都创建新实例
```csharp
services.AddTransient<IService, Service>();
```
- 适用于轻量级、无状态的服务
- 每次注入都是新实例

**Scoped（作用域）**：每个请求/作用域内共享同一实例
```csharp
services.AddScoped<IService, Service>();
```
- 适用于需要在同一请求内共享状态的服务
- ASP.NET Core 中每个 HTTP 请求一个作用域

**Singleton（单例）**：整个应用程序生命周期内共享同一实例
```csharp
services.AddSingleton<IService, Service>();
```
- 适用于全局共享的服务（如配置、缓存）
- 注意线程安全问题


## 工厂模式注册

使用工厂方法注册服务：
```csharp
// 简单工厂
services.AddTransient<IService>(provider =>
{
    var config = provider.GetRequiredService<IConfiguration>();
    return new Service(config);
});

// 工厂类
services.AddSingleton<IServiceFactory, ServiceFactory>();
```

## 多实现注册

注册同一接口的多个实现：
```csharp
// 注册多个实现
services.AddTransient<INotification, EmailNotification>();
services.AddTransient<INotification, SmsNotification>();
services.AddTransient<INotification, PushNotification>();

// 注入所有实现
public class NotificationService
{
    private readonly IEnumerable<INotification> _notifications;

    public NotificationService(IEnumerable<INotification> notifications)
    {
        _notifications = notifications;
    }

    public void Notify(string message)
    {
        foreach (var notification in _notifications)
        {
            notification.Send(message);
        }
    }
}

// 注入特定实现
services.AddKeyedTransient<INotification, EmailNotification>("email");
services.AddKeyedTransient<INotification, SmsNotification>("sms");
```


## 服务解析

**GetService vs GetRequiredService**：
```csharp
// GetService：找不到返回 null
var service = serviceProvider.GetService<IService>();

// GetRequiredService：找不到抛出异常
var service = serviceProvider.GetRequiredService<IService>();
```

**注入 IEnumerable<T>**：
```csharp
var services = serviceProvider.GetServices<INotification>();
```


## 最佳实践

1. **优先使用构造函数注入**：明确依赖关系
2. **避免在服务定位器模式中使用**：直接注入依赖
3. **正确选择生命周期**：根据服务特性选择 Transient/Scoped/Singleton
4. **避免循环依赖**：重构代码消除循环依赖
5. **使用接口而非具体类**：提高可测试性和灵活性


## 与第三方容器集成

.NET Core 支持与第三方 DI 容器集成：
- Autofac
- Ninject
- StructureMap
- Unity

using System;
using System.Collections.Generic;
using Microsoft.Extensions.DependencyInjection;

namespace DependencyInjectionDemo
{
    // 接口定义
    public interface IEmailService
    {
        void SendEmail(string to, string subject, string body);
    }

    public interface ISmsService
    {
        void SendSms(string phoneNumber, string message);
    }

    public interface INotificationService
    {
        void Notify(string message);
    }

    // 实现类
    public class SmtpEmailService : IEmailService
    {
        public void SendEmail(string to, string subject, string body)
        {
            Console.WriteLine($"发送邮件到 {to}: {subject}");
        }
    }

    public class TwilioSmsService : ISmsService
    {
        public void SendSms(string phoneNumber, string message)
        {
            Console.WriteLine($"发送短信到 {phoneNumber}: {message}");
        }
    }

    // 聚合服务
    public class NotificationService : INotificationService
    {
        private readonly IEmailService _emailService;
        private readonly ISmsService _smsService;

        // 构造函数注入
        public NotificationService(IEmailService emailService, ISmsService smsService)
        {
            _emailService = emailService;
            _smsService = smsService;
        }

        public void Notify(string message)
        {
            _emailService.SendEmail("user@example.com", "通知", message);
            _smsService.SendSms("+8613800138000", message);
        }
    }

    // 多实现示例
    public interface IRepository<T>
    {
        T GetById(int id);
        void Add(T entity);
    }

    public class CachedRepository<T> : IRepository<T> where T : class
    {
        private readonly IRepository<T> _inner;
        private readonly Dictionary<int, T> _cache = new();

        public CachedRepository(IRepository<T> inner)
        {
            _inner = inner;
        }

        public T GetById(int id)
        {
            if (!_cache.TryGetValue(id, out var entity))
            {
                entity = _inner.GetById(id);
                _cache[id] = entity;
            }
            return entity;
        }

        public void Add(T entity)
        {
            _inner.Add(entity);
        }
    }

    public class SqlRepository<T> : IRepository<T> where T : class
    {
        public T GetById(int id)
        {
            Console.WriteLine($"从数据库获取 {typeof(T).Name} {id}");
            return null; // 简化示例
        }

        public void Add(T entity)
        {
            Console.WriteLine($"添加 {typeof(T).Name} 到数据库");
        }
    }

    // 工厂模式
    public interface IConnectionFactory
    {
        string CreateConnection();
    }

    public class SqlConnectionFactory : IConnectionFactory
    {
        private readonly string _connectionString;

        public SqlConnectionFactory(string connectionString)
        {
            _connectionString = connectionString;
        }

        public string CreateConnection() => _connectionString;
    }

    // 生命周期演示
    public interface IOperation
    {
        Guid OperationId { get; }
    }

    public interface ITransientOperation : IOperation { }
    public interface IScopedOperation : IOperation { }
    public interface ISingletonOperation : IOperation { }

    public class Operation : ITransientOperation, IScopedOperation, ISingletonOperation
    {
        public Guid OperationId { get; } = Guid.NewGuid();
    }

    // 服务使用
    public class MyService
    {
        private readonly ITransientOperation _transient;
        private readonly IScopedOperation _scoped;
        private readonly ISingletonOperation _singleton;

        public MyService(
            ITransientOperation transient,
            IScopedOperation scoped,
            ISingletonOperation singleton)
        {
            _transient = transient;
            _scoped = scoped;
            _singleton = singleton;
        }

        public void ShowIds()
        {
            Console.WriteLine($"Transient: {_transient.OperationId}");
            Console.WriteLine($"Scoped: {_scoped.OperationId}");
            Console.WriteLine($"Singleton: {_singleton.OperationId}");
        }
    }

    class Program
    {
        static void Main()
        {
            // 配置 DI 容器
            var services = new ServiceCollection();

            // 注册服务
            services.AddTransient<IEmailService, SmtpEmailService>();
            services.AddTransient<ISmsService, TwilioSmsService>();
            services.AddTransient<INotificationService, NotificationService>();

            // 工厂模式注册
            services.AddSingleton<IConnectionFactory>(provider =>
            {
                return new SqlConnectionFactory("Server=localhost;Database=MyDb");
            });

            // 生命周期注册
            services.AddTransient<ITransientOperation, Operation>();
            services.AddScoped<IScopedOperation, Operation>();
            services.AddSingleton<ISingletonOperation, Operation>();
            services.AddTransient<MyService>();

            // 构建服务提供者
            var serviceProvider = services.BuildServiceProvider();

            // 使用服务
            var notificationService = serviceProvider.GetRequiredService<INotificationService>();
            notificationService.Notify("Hello DI!");

            // 生命周期演示
            Console.WriteLine("\n=== 生命周期演示 ===");
            using (var scope1 = serviceProvider.CreateScope())
            {
                var service1 = scope1.ServiceProvider.GetRequiredService<MyService>();
                service1.ShowIds();

                Console.WriteLine("\n同一作用域内：");
                var service2 = scope1.ServiceProvider.GetRequiredService<MyService>();
                service2.ShowIds();
            }

            Console.WriteLine("\n新作用域：");
            using (var scope2 = serviceProvider.CreateScope())
            {
                var service3 = scope2.ServiceProvider.GetRequiredService<MyService>();
                service3.ShowIds();
            }

            // 获取所有实现
            Console.WriteLine("\n=== 多实现 ===");
            var services2 = new ServiceCollection();
            services2.AddTransient<IEmailService, SmtpEmailService>();
            // 可以注册更多实现
            var provider2 = services2.BuildServiceProvider();
            var emailService = provider2.GetRequiredService<IEmailService>();
            emailService.SendEmail("test@test.com", "Test", "Hello");
        }
    }
}
